#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES — uno-bot gets its own write identity on the uno-blueprint project.
#
# The identity is an ordinary Supabase Auth user, uno-bot@uno-blueprint.local,
# whose app_metadata.role is `rpc_writer`. plus-uno-blueprint's migration
# 20261015120000_uno_bot_writes_through_the_rpcs_alone.sql is what gives that
# role its meaning: it passes the guard inside every SECURITY DEFINER
# authoring RPC, fails every write policy (so no raw table write), cannot
# delete, and writes a status through `upsert_cell_at_status` /
# `set_path_status`, which record themselves in authoring_changes with the
# bot's own author_id. The Worker signs in with the password grant for a
# one-hour JWT. Never a service-role key.
#
# WHAT THIS WIZARD REFUSES TO DO FOR YOU. It never creates the account, never
# chooses or types the password, and never writes it anywhere: you make the
# user in the dashboard, and `npm run secrets:set` takes the password on your
# own terminal with echo off and hands it to wrangler on stdin. The last stage
# asks for it once more, hidden, to sign in and prove the write path; it lives
# in this shell's memory for that stage and is unset after. The only values
# persisted are public ones (the anon key, the user's id, a checkout path),
# into the untracked .blueprint-writer.env, so a re-run resumes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

BOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="$(cd "$BOT_DIR/../.." && pwd)"
ENV_FILE="$REPO_ROOT/.blueprint-writer.env"

PROJECT_REF="osybxeojvsqcwxkgnalm"
SUPABASE_URL="https://${PROJECT_REF}.supabase.co"
DASHBOARD="https://supabase.com/dashboard/project/${PROJECT_REF}"
BOT_EMAIL="$(sed -n 's/^SUPABASE_WRITE_EMAIL *= *"\(.*\)"/\1/p' "$BOT_DIR/wrangler.toml" | head -n1)"
MIGRATION="20261015120000"
MIGRATION_FILE="supabase/migrations/${MIGRATION}_uno_bot_writes_through_the_rpcs_alone.sql"
FAILED=()

pass() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; FAILED+=("$1"); }

banner "uno-bot · blueprint write identity"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools"
say "This wizard needs curl, jq, uuidgen and node, and wrangler logged in to"
say "the Cloudflare account uno-bot runs on."
missing=0
for tool in curl jq uuidgen node npm; do
  if command -v "$tool" >/dev/null 2>&1; then note "✓ $tool"; else warn "$tool is not installed"; missing=1; fi
done
if [[ -z "$BOT_EMAIL" ]]; then
  warn "wrangler.toml has no SUPABASE_WRITE_EMAIL. Run this from a checkout that has this change."
  missing=1
else
  note "✓ the bot's address, from wrangler.toml: $BOT_EMAIL"
fi
(( missing )) && { warn "Install what is missing, then re-run."; exit 1; }
WRANGLER="$BOT_DIR/node_modules/.bin/wrangler"
[[ -x "$WRANGLER" ]] || { warn "agents/uno-bot has no node_modules: run 'npm ci' in agents/uno-bot, then re-run."; exit 1; }
if ! (cd "$BOT_DIR" && "$WRANGLER" whoami >/dev/null 2>&1); then
  confirm "wrangler is not logged in. Run 'wrangler login' now?" && (cd "$BOT_DIR" && "$WRANGLER" login) || true
fi
pause "Continue?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the uno-bot Auth user"
say "You create the account; the wizard only needs its id afterwards."
step "In your password manager, generate a password of 32+ random characters"
step "and save it as \"uno-bot · uno-blueprint writer\" with the address $BOT_EMAIL."
open_url "$DASHBOARD/auth/users"
step "Authentication → Users → Add user → Create new user."
step "Email: $BOT_EMAIL"
step "Password: the one you just generated."
step "Tick \"Auto Confirm User\" (the address has no mailbox), then Create user."
step "Click the new row and copy its User UID."
note "If the dashboard labels differ, the end state is what matters: a confirmed"
note "email user with that address. Leave its metadata alone; the migration sets it."
ask BOT_USER_ID "Paste the User UID:"
[[ "$BOT_USER_ID" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] \
  || { warn "That is not a UUID. Re-run and paste the User UID."; exit 1; }
write_env BOT_USER_ID "$BOT_USER_ID"
pause "Continue?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Apply the migration in plus-uno-blueprint"
say "The SQL lives in plus-uno-blueprint, reviewed as its own pull request:"
note "  $MIGRATION_FILE"
say "It redefines is_service_account() for the rpc_writer tier, adds the two"
say "self-recording status RPCs and the delete guard, and grants the claim to"
say "$BOT_EMAIL. Apply it once that pull request is merged and pulled."
ask BLUEPRINT_DIR "Path to your plus-uno-blueprint checkout:"
BLUEPRINT_DIR="${BLUEPRINT_DIR/#\~/$HOME}"
if [[ ! -f "$BLUEPRINT_DIR/$MIGRATION_FILE" ]]; then
  warn "No $MIGRATION_FILE there. Merge the pull request, pull main, then re-run."
  exit 1
fi
write_env BLUEPRINT_DIR "$BLUEPRINT_DIR"
say "apply:pending reads SUPABASE_DB_URL from that checkout's .env.local, lists"
say "what it would apply from $MIGRATION on, and applies only with --apply."
(cd "$BLUEPRINT_DIR" && npm run --silent apply:pending -- --from="$MIGRATION") \
  || { warn "The dry run failed; fix what it says (usually SUPABASE_DB_URL), then re-run."; exit 1; }
if confirm "Apply exactly the list above to production?"; then
  (cd "$BLUEPRINT_DIR" && npm run --silent apply:pending -- --from="$MIGRATION" --apply) \
    || { warn "The apply failed and rolled back. Nothing is half-done; read the error, then re-run."; exit 1; }
  pass "migration applied"
else
  warn "Not applied. Nothing after this works until it is; re-run when ready."
  exit 1
fi
say "The claim is set by the migration only if the user existed when it ran."
open_url "$DASHBOARD/sql/new"
step "Run this in the SQL editor; it must say rpc_writer:"
note "  select raw_app_meta_data->>'role' from auth.users where id = '$BOT_USER_ID';"
step "If it says anything else, run this once, then check again:"
note "  update auth.users set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)"
note "    || '{\"role\":\"rpc_writer\"}'::jsonb where id = '$BOT_USER_ID';"
pause "It says rpc_writer. Continue?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Put the password on the Worker"
say "The Worker reads SUPABASE_WRITE_EMAIL from [vars] (already committed) and"
say "SUPABASE_WRITE_PASSWORD from its secrets. You type the password into the"
say "prompt below; it goes to wrangler on stdin and is never echoed or stored."
warn "wrangler secret put deploys a new version of the Worker with the secret."
note "  It ships the code that is live now; nothing reads the secret until the"
note "  blueprint write tool lands."
if confirm "Set SUPABASE_WRITE_PASSWORD on uno-bot now?"; then
  (cd "$BOT_DIR" && npm run --silent secrets:set -- --only SUPABASE_WRITE_PASSWORD) \
    && WRITTEN_SECRET+=("SUPABASE_WRITE_PASSWORD (Cloudflare, uno-bot)") \
    || SKIPPED+=("SUPABASE_WRITE_PASSWORD: cd agents/uno-bot && npm run secrets:set -- --only SUPABASE_WRITE_PASSWORD")
else
  SKIPPED+=("SUPABASE_WRITE_PASSWORD: cd agents/uno-bot && npm run secrets:set -- --only SUPABASE_WRITE_PASSWORD")
fi
pause "Continue?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prove it: a proposed write, its revert, and the walls"
say "Signs in as uno-bot, then on one cell that is already 'proposed':"
note "  1. a direct table PATCH (must change nothing)"
note "  2. upsert_cell_at_status, status proposed, content + ' [uno-bot write check]'"
note "  3. the same RPC with the previous content and status (the revert)"
note "  4. the cell reads back exactly as it was; authoring_changes holds both"
note "     writes under the bot's own author_id"
say "The cell stays 'proposed' throughout, so the live board never changes"
say "meaning; the two audit rows are permanent, as every write's are."
open_url "$DASHBOARD/settings/api-keys"
step "Copy the anon public key (the Legacy API Keys tab, the key the Worker's"
step "SUPABASE_ANON_KEY holds). It is public: it ships in the blueprint app."
ask SUPABASE_ANON_KEY "Paste the anon key:"
write_env SUPABASE_ANON_KEY "$SUPABASE_ANON_KEY"
say "Now the password once more, from your password manager. Hidden, held in"
say "memory for this stage only, and sent only to $SUPABASE_URL."
read -rs -p "  ${BOLD}uno-bot password:${RESET} " BOT_PASSWORD; printf '\n'

# The password and the token travel on stdin, never argv, which every user on
# this machine can read with ps.
TOKEN="$(E="$BOT_EMAIL" P="$BOT_PASSWORD" jq -n '{email: env.E, password: env.P}' \
  | curl -sS -X POST "$SUPABASE_URL/auth/v1/token?grant_type=password" \
      -H "apikey: $SUPABASE_ANON_KEY" -H 'Content-Type: application/json' --data-binary @- \
  | jq -r '.access_token // empty' || true)"
unset BOT_PASSWORD

api() { # METHOD PATH [BODY]
  local method="$1" path="$2" body="${3:-}"
  local -a data=()
  [[ -n "$body" ]] && data=(--data-binary "$body")
  printf 'header = "Authorization: Bearer %s"\n' "$TOKEN" \
    | curl -sS -K - -X "$method" "$SUPABASE_URL$path" \
        -H "apikey: $SUPABASE_ANON_KEY" -H 'Content-Type: application/json' \
        -H 'Prefer: return=representation' "${data[@]+"${data[@]}"}"
}

if [[ -z "$TOKEN" ]]; then
  fail "sign-in refused: check the address, the password and Auto Confirm"
else
  CLAIMS="$(printf '%s' "$TOKEN" | node -e '
    let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => {
      const p = JSON.parse(Buffer.from(s.split(".")[1], "base64url"));
      console.log(JSON.stringify({ sub: p.sub, role: p.app_metadata?.role ?? null }));
    });')"
  [[ "$(jq -r .sub <<<"$CLAIMS")" == "$BOT_USER_ID" ]] && pass "signed in as the uno-bot user" \
    || fail "signed in, but as $(jq -r .sub <<<"$CLAIMS"), not $BOT_USER_ID"
  [[ "$(jq -r .role <<<"$CLAIMS")" == "rpc_writer" ]] && pass "the JWT carries app_metadata.role = rpc_writer" \
    || fail "the JWT's app_metadata.role is $(jq -r .role <<<"$CLAIMS"), not rpc_writer (stage 3's SQL, then re-run)"
fi

if (( ${#FAILED[@]} == 0 )); then
  CELL="$(api GET '/rest/v1/cells?status=eq.proposed&position=eq.0&select=id,path_id,lane_id,step_id,content,status&order=id&limit=1' | jq -c '.[0] // empty' || true)"
  if [[ -z "$CELL" ]]; then
    fail "no proposed cell to test on; nothing was written"
  else
    CELL_ID="$(jq -r .id <<<"$CELL")"
    ORIGINAL="$(jq -r .content <<<"$CELL")"
    note "test cell: $CELL_ID"

    # 1. The wall. The PATCH writes the cell's own content back, so even if the
    #    wall were down it would change nothing; a refusal returns no rows.
    PATCHED="$(api PATCH "/rest/v1/cells?id=eq.$CELL_ID" "$(jq -c '{content}' <<<"$CELL")" || true)"
    [[ "$PATCHED" == "[]" ]] && pass "a direct table PATCH changed no row" \
      || fail "a direct table PATCH was accepted: $PATCHED (the bot can write tables; stop and look)"

    SESSION_ID="$(uuidgen | tr 'A-Z' 'a-z')"
    if (( ${#FAILED[@]} == 0 )) && confirm "Write the test edit to cell $CELL_ID and revert it?"; then
      # 2. The write.
      WRITE_BODY="$(jq -c --arg s "$SESSION_ID" '{path_id, lane_id, step_id,
        content: (.content + " [uno-bot write check]"), status: "proposed", agent_session_id: $s}' <<<"$CELL")"
      WROTE="$(api POST /rest/v1/rpc/upsert_cell_at_status "$WRITE_BODY" || true)"
      if [[ "$(jq -r '.inserted' <<<"$WROTE" 2>/dev/null || true)" == "false" ]]; then
        pass "upsert_cell_at_status wrote the proposed edit"
        # 3. The revert, from what the write said was there before.
        REVERT_BODY="$(jq -c --arg s "$SESSION_ID" --argjson w "$WROTE" '{path_id, lane_id, step_id,
          content: $w.previous.content, status: $w.previous.status, agent_session_id: $s}' <<<"$CELL")"
        REVERTED="$(api POST /rest/v1/rpc/upsert_cell_at_status "$REVERT_BODY" || true)"
        [[ "$(jq -r '.inserted' <<<"$REVERTED" 2>/dev/null || true)" == "false" ]] && pass "the revert ran" \
          || fail "the revert failed: $REVERTED"
      else
        fail "upsert_cell_at_status refused: $WROTE"
      fi

      # 4. Read back, and the record.
      NOW="$(api GET "/rest/v1/cells?id=eq.$CELL_ID&select=content,status" | jq -c '.[0]' || true)"
      if [[ "$(jq -r .content <<<"$NOW")" == "$ORIGINAL" && "$(jq -r .status <<<"$NOW")" == "proposed" ]]; then
        pass "the cell reads back exactly as it was"
      else
        fail "the cell did not come back: it reads $NOW"
        warn "Restore it by hand in the canvas. Its content was:"
        note "  $ORIGINAL"
      fi
      LOG="$(api GET "/rest/v1/authoring_changes?agent_session_id=eq.$SESSION_ID&select=fn,author,author_id&order=at" || true)"
      if [[ "$(jq '[.[] | select(.fn == "upsert_cell_at_status" and .author == "agent" and .author_id == "'"$BOT_USER_ID"'")] | length' <<<"$LOG")" == "2" ]]; then
        pass "authoring_changes holds both writes under the bot's author_id (session $SESSION_ID)"
      else
        fail "authoring_changes for session $SESSION_ID reads $LOG"
      fi
    fi
  fi
fi
unset TOKEN

if (( ${#FAILED[@]} )); then
  printf '\n'; warn "verification failed:"
  for f in "${FAILED[@]}"; do note "  - $f"; done
  SKIPPED+=("verification (stage 5) — re-run the wizard once fixed")
fi
pause "Continue to the summary?"

finish
note "Deletes stay human-only: the delete guard was proven against a local database,"
note "not here, because proving it here means calling delete_cell on a real cell."
note "Next: plus-uno-blueprint regenerates deployment/types/database.ts for the two"
note "new RPCs (docs/engineering/access-and-security.md § Regenerating)."
(( ${#FAILED[@]} )) && exit 1 || exit 0
